// Serves public pages from the edge cache so most visits skip Next and the free plan's CPU limit (Error 1102).
// @ts-ignore generated by OpenNext at build time, absent during next build
import handler from './.open-next/worker.js'
import { dueUrls, submitIndexNow } from './src/lib/indexnow'
import { isProdHost } from './src/lib/host'
import { withHostPolicy } from './src/lib/host-policy'
import { legacyRedirect } from './src/lib/legacy'

// Low traffic means most visits would be cache misses at 5 minutes, and a miss is what risks Error 1102.
const TTL_SECONDS = 6 * 60 * 60
// Bump to drop every cached page on the next deploy, for example after a data push.
const CACHE_VERSION = 1
const NEVER_CACHE = /^\/(admin|api|search)(\/|$)/

export default {
  async fetch(request: Request, env: unknown, ctx: { waitUntil(promise: Promise<unknown>): void }) {
    const url = new URL(request.url)
    return withHostPolicy(await serve(request, url, env, ctx), url.hostname)
  },
  async scheduled(_event: unknown, env: { SITE_HOST?: string }, ctx: { waitUntil(promise: Promise<unknown>): void }) {
    if (!isProdHost(env.SITE_HOST ?? null)) return
    ctx.waitUntil(
      fetch('https://nutrifit.kr/rss.xml')
        .then((res) => res.text())
        .then((xml) => submitIndexNow(dueUrls(xml, new Date()))),
    )
  },
}

async function serve(request: Request, url: URL, env: unknown, ctx: { waitUntil(promise: Promise<unknown>): void }): Promise<Response> {
  if (url.pathname === '/robots.txt' && !isProdHost(url.hostname)) {
    return new Response('User-agent: *\nDisallow: /\n', { headers: { 'content-type': 'text/plain; charset=utf-8' } })
  }
  const legacy = request.method === 'GET' || request.method === 'HEAD' ? legacyRedirect(url) : null
  if (legacy?.status === 301) return Response.redirect(legacy.location, 301)
  if (legacy?.status === 410) return new Response('Gone', { status: 410 })
  const signedIn = (request.headers.get('cookie') ?? '').includes('payload-token')
  if (request.method !== 'GET' || signedIn || NEVER_CACHE.test(url.pathname)) {
    return handler.fetch(request, env, ctx)
  }
  // Next answers the same URL with HTML or a client-side payload depending on these headers.
  const key = new Request(`${url.href}${url.search ? '&' : '?'}__v=${CACHE_VERSION}-${request.headers.get('rsc') ?? 'html'}`)
  const cache = (caches as unknown as { default: Cache }).default
  const hit = await cache.match(key)
  if (hit) return hit
  const response: Response = await handler.fetch(request, env, ctx)
  if (response.status === 200 && !response.headers.has('set-cookie')) {
    const copy = new Response(response.clone().body, response)
    copy.headers.set('cache-control', `public, s-maxage=${TTL_SECONDS}`)
    ctx.waitUntil(cache.put(key, copy))
  }
  return response
}
